        if choice == "1":
            title = input("Title: ").strip()
            priority = input("Priority (low/normal/high): ").strip().lower() or "normal"
            if title and priority in {"low", "normal", "high"}:
                items.append(WorkItem(title, priority))
            else:
                print("Use a title and a valid priority.")
        elif choice == "2":
            list_items(items)
        elif choice == "3":
            try:
                index = int(input("Item number: ")) - 1
                items[index].done = True
            except (ValueError, IndexError):
                print("Invalid item number.")
        elif choice == "4":
            save_items(items)
            logging.info("Saved %d items", len(items))
        elif choice == "5":
            save_items(items)
            print("Saved. Goodbye!")
            break
        else:
            print("Choose a number from 1 to 5.")

main()
